#!/usr/bin/env python3
import sys, os, re, json, termios, tty, select, shutil, subprocess, time
from dataclasses import dataclass, field

HELP = """
Usage: peco [options] [FILE]

Options:
  -h, --help            show this help message and exit
  --query               initial value for query
  --rcfile              path to the settings file
  --version             print the version and exit
  -b, --buffer-size     number of lines to keep in search buffer
  --null                expect NUL (\\0) as separator for target/output
  --initial-index       position of the initial index of the selection (0 base)
  --initial-filter      specify the default filter
  --prompt              specify the prompt string
  --layout              layout to be used. 'top-down', 'bottom-up', or 'top-down-query-bottom'. default is 'top-down'
  --select-1            select first item and immediately exit if the input contains only 1 item
  --exit-0              exit immediately with status 1 if the input is empty
  --select-all          select all items and immediately exit
  --on-cancel           specify action on user cancel. 'success' or 'error'.
                        default is 'success'. This may change in future versions
  --selection-prefix    use a prefix instead of changing line color to indicate currently selected lines.
                        default is to use colors. This option is experimental
  --exec                execute command instead of finishing/terminating peco.
                        Please note that this command will receive selected line(s) from stdin,
                        and will be executed via '/bin/sh -c' or 'cmd /c'
  --print-query         print out the current query as first line of output
  --ansi                enable ANSI color code support
  --height              display height in lines or percentage (e.g. '10', '50%')
"""
VERSION = "peco version v0.5.11 (built with go1.25.0)\n"
FILTERS = ["IgnoreCase", "CaseSensitive", "SmartCase", "IRegexp", "Regexp", "Fuzzy"]
ANSI_RE = re.compile(r'\x1b\[[0-9;?]*[ -/]*[@-~]')

@dataclass
class Opts:
    query: str = ""
    rcfile: str|None = None
    buffer_size: int|None = None
    null: bool = False
    initial_index: int = 0
    initial_filter: str = "IgnoreCase"
    prompt: str = "QUERY>"
    layout: str = "top-down"
    select_1: bool = False
    exit_0: bool = False
    select_all: bool = False
    on_cancel: str = "success"
    selection_prefix: str|None = None
    exec_cmd: str|None = None
    print_query: bool = False
    ansi: bool = False
    height: str|None = None
    suppress_status: bool = False
    keymap: dict = field(default_factory=dict)

class ParseError(Exception):
    def __init__(self, msg, show_help=True):
        super().__init__(msg); self.msg=msg; self.show_help=show_help

class SetupError(Exception): pass


def parse_int_flag(flag_display, val):
    try:
        return int(val, 10)
    except Exception:
        msg = f"invalid argument for flag `{flag_display}' (expected int): strconv.ParseInt: parsing \"{val}\": invalid syntax"
        raise ParseError(msg)


def need_value(args, i, flag, allow_dash_value=False):
    if i+1 >= len(args):
        raise ParseError(f"expected argument for flag `{flag}'")
    nxt = args[i+1]
    if nxt.startswith('-') and not allow_dash_value:
        raise ParseError(f"expected argument for flag `{flag}', but got option `{nxt}'")
    return nxt, i+1


def parse_args(argv):
    opts = Opts(); positionals=[]; i=0
    while i < len(argv):
        a = argv[i]
        if a == '--':
            positionals.extend(argv[i+1:]); break
        if positionals or not a.startswith('-') or a == '-':
            positionals.extend(argv[i:]); break
        if a in ('-h','--help'):
            sys.stdout.write(HELP); sys.exit(0)
        if a == '--version':
            sys.stdout.write(VERSION); sys.exit(0)
        if a.startswith('--'):
            if '=' in a:
                name, val = a[2:].split('=',1)
                had_eq=True
            else:
                name, val, had_eq = a[2:], None, False
            bools = {'null','select-1','exit-0','select-all','print-query','ansi'}
            vals = {'query','rcfile','buffer-size','initial-index','initial-filter','prompt','layout','on-cancel','selection-prefix','exec','height'}
            if name in bools:
                if name == 'null': opts.null=True
                elif name == 'select-1': opts.select_1=True
                elif name == 'exit-0': opts.exit_0=True
                elif name == 'select-all': opts.select_all=True
                elif name == 'print-query': opts.print_query=True
                elif name == 'ansi': opts.ansi=True
                i += 1; continue
            if name not in vals:
                raise ParseError(f"unknown flag `{name}'")
            if val is None:
                # Go option parser accepts '-' and negative numeric values for numeric flags.
                allow = name in ('buffer-size','initial-index')
                if name == 'query':
                    # a single hyphen is a legal query; longer dash-prefixed strings are options
                    if i+1 >= len(argv):
                        raise ParseError("expected argument for flag `--query'")
                    nxt=argv[i+1]
                    if nxt.startswith('-') and nxt != '-':
                        raise ParseError(f"expected argument for flag `--query', but got option `{nxt}'")
                    val=nxt; i += 1
                else:
                    val, i = need_value(argv, i, '--'+name, allow_dash_value=allow)
            if name == 'query': opts.query = val
            elif name == 'rcfile': opts.rcfile = val
            elif name == 'buffer-size': opts.buffer_size = parse_int_flag('-b, --buffer-size', val)
            elif name == 'initial-index': opts.initial_index = parse_int_flag('--initial-index', val)
            elif name == 'initial-filter': opts.initial_filter = val
            elif name == 'prompt': opts.prompt = val
            elif name == 'layout': opts.layout = val
            elif name == 'on-cancel': opts.on_cancel = val
            elif name == 'selection-prefix': opts.selection_prefix = val
            elif name == 'exec': opts.exec_cmd = val
            elif name == 'height': opts.height = val
            i += 1; continue
        if a == '-b':
            val, i = need_value(argv, i, '-b, --buffer-size', allow_dash_value=True)
            opts.buffer_size = parse_int_flag('-b, --buffer-size', val)
            i += 1; continue
        if a.startswith('-b='):
            opts.buffer_size = parse_int_flag('-b, --buffer-size', a[3:]); i += 1; continue
        raise ParseError(f"unknown flag `{a[1:]}'")
    return opts, positionals


def parse_scalar(v):
    v=v.strip()
    if not v: return ""
    if v.lower() == 'true': return True
    if v.lower() == 'false': return False
    if (v.startswith('"') and v.endswith('"')) or (v.startswith("'") and v.endswith("'")):
        return v[1:-1]
    try:
        return int(v)
    except Exception:
        return v


def load_config(path):
    try:
        data = open(path, 'r', encoding='utf-8').read()
    except OSError as e:
        raise SetupError(f"failed to setup configuration: failed to read config file: failed to open file {path}: {e}")
    try:
        if path.endswith(('.yaml','.yml')):
            cfg={}
            for line in data.splitlines():
                line=line.split('#',1)[0].rstrip()
                if not line.strip() or ':' not in line or line.lstrip().startswith('-'):
                    continue
                k,v=line.split(':',1); cfg[k.strip().strip('"\'')] = parse_scalar(v)
            return cfg
        return json.loads(data or '{}')
    except Exception as e:
        raise SetupError(f"failed to setup configuration: failed to parse config file: {e}")


def apply_config(opts, cli_opts, argv):
    # Load requested rcfile, or a common default if present.
    path = opts.rcfile
    if not path:
        home=os.path.expanduser('~')
        for p in (os.path.join(home,'.config','peco','config.json'), os.path.join(home,'.peco','config.json')):
            if os.path.exists(p): path=p; break
    if path:
        cfg = load_config(path)
        if isinstance(cfg, dict):
            if 'Prompt' in cfg and not any(a.startswith('--prompt') for a in argv): opts.prompt=str(cfg['Prompt'])
            if 'InitialFilter' in cfg and not any(a.startswith('--initial-filter') for a in argv): opts.initial_filter=str(cfg['InitialFilter'])
            if 'OnCancel' in cfg and not any(a.startswith('--on-cancel') for a in argv): opts.on_cancel=str(cfg['OnCancel'])
            if 'Layout' in cfg and not any(a.startswith('--layout') for a in argv): opts.layout=str(cfg['Layout'])
            if 'ANSI' in cfg and not any(a == '--ansi' for a in argv): opts.ansi=bool(cfg['ANSI'])
            if 'Height' in cfg and not any(a.startswith('--height') for a in argv): opts.height=str(cfg['Height'])
            if 'SuppressStatusMsg' in cfg: opts.suppress_status=bool(cfg['SuppressStatusMsg'])
            if isinstance(cfg.get('Keymap'), dict): opts.keymap=cfg.get('Keymap')
    # Validate
    if opts.layout not in ('top-down','bottom-up','top-down-query-bottom'):
        raise ParseError(f"invalid command line arguments: unknown layout: '{opts.layout}'", show_help=False)
    if opts.initial_filter not in FILTERS:
        raise SetupError("failed to apply configuration: failed to populate initial filter: failed to set filter: specified filter was not found")
    if opts.on_cancel not in ('success','error'):
        raise SetupError(f"failed to apply configuration: invalid --on-cancel value: invalid OnCancel value \"{opts.on_cancel}\": must be \"success\" or \"error\"")
    if opts.height is not None and not re.fullmatch(r'[0-9]+%?', str(opts.height)):
        raise SetupError(f"failed to apply configuration: failed to parse height specification: invalid height specification: \"{opts.height}\"")

@dataclass
class Item:
    display: str
    output: str
    plain: str
    index: int


def split_lines(data: bytes):
    # bufio.Scanner-style lines: final unterminated line is still a token.
    if not data:
        return []
    text=data.decode('utf-8', errors='replace')
    parts=text.split('\n')
    if parts and parts[-1] == '':
        parts=parts[:-1]
    return parts


def read_items(opts, positionals):
    if positionals:
        path=positionals[0]
        try:
            data=open(path,'rb').read()
        except OSError as e:
            raise SetupError(f"failed to setup input source: failed to open file for input: {e}")
    else:
        # If stdin is a terminal, there is no piped input to consume.
        if sys.stdin.isatty(): data=b''
        else: data=sys.stdin.buffer.read()
    raw_lines=split_lines(data)
    if opts.buffer_size is not None and opts.buffer_size > 0 and len(raw_lines) > opts.buffer_size:
        raw_lines = raw_lines[-opts.buffer_size:]
    items=[]
    for idx,line in enumerate(raw_lines):
        if opts.null and '\x00' in line:
            disp,out=line.split('\x00',1)
        else:
            disp,out=line,line
        plain=ANSI_RE.sub('', disp) if opts.ansi else disp
        items.append(Item(disp,out,plain,idx))
    return items


def output_lines(opts, query, items):
    if opts.print_query:
        sys.stdout.write(query + '\n')
    for it in items:
        sys.stdout.write(it.output + '\n')
    sys.stdout.flush()


def parse_query_terms(q):
    pos=[]; neg=[]
    for tok in q.split():
        if tok.startswith('\\-'):
            pos.append(tok[1:])
        elif tok.startswith('-') and len(tok) > 1:
            neg.append(tok[1:])
        else:
            pos.append(tok)
    return pos, neg


def smart_case(q):
    return not any(c.isalpha() and c.isupper() for c in q)


def fuzzy_match(text, pat, ignore):
    if pat == '': return True
    if ignore:
        text=text.lower(); pat=pat.lower()
    j=0
    for ch in text:
        if j < len(pat) and ch == pat[j]: j += 1
        if j == len(pat): return True
    return False


def regex_search(pat, text, flags=0):
    try:
        return re.search(pat, text, flags) is not None
    except re.error:
        return False


def item_matches(it, q, filt):
    if q == '': return True
    pos, neg = parse_query_terms(q)
    text=it.plain
    if filt == 'IgnoreCase':
        lt=text.lower()
        for t in pos:
            if t.lower() not in lt: return False
        for t in neg:
            if t.lower() in lt: return False
        return True
    if filt == 'CaseSensitive':
        for t in pos:
            if t not in text: return False
        for t in neg:
            if t in text: return False
        return True
    if filt == 'SmartCase':
        ign=smart_case(q); hay=text.lower() if ign else text
        for t in pos:
            tt=t.lower() if ign else t
            if tt not in hay: return False
        for t in neg:
            tt=t.lower() if ign else t
            if tt in hay: return False
        return True
    if filt == 'Regexp':
        for t in pos:
            if not regex_search(t, text): return False
        for t in neg:
            if regex_search(t, text): return False
        return True
    if filt == 'IRegexp':
        for t in pos:
            if not regex_search(t, text, re.I): return False
        for t in neg:
            if regex_search(t, text, re.I): return False
        return True
    if filt == 'Fuzzy':
        ign=smart_case(q)
        for t in pos:
            if not fuzzy_match(text, t, ign): return False
        flags=re.I if ign else 0
        for t in neg:
            if regex_search(t, text, flags): return False
        return True
    return True


def filtered(items, q, filt, toggle_query=False):
    if toggle_query: return list(items)
    return [it for it in items if item_matches(it, q, filt)]


def screen_error_and_exit():
    term=os.environ.get('TERM','')
    if not term:
        sys.stderr.write("Error: failed to initialize screen: failed to create tcell screen: terminal entry not found: term not set\n")
    else:
        sys.stderr.write("Error: failed to initialize screen: failed to initialize tcell screen: open /dev/tty: no such device or address\n")
    sys.exit(1)


def terminal_size():
    try: return shutil.get_terminal_size((80,24))
    except Exception: return os.terminal_size((80,24))


def clamp(n, lo, hi):
    if hi < lo: return lo
    return max(lo, min(hi, n))


def render(ttyf, opts, query, filt, view, sel, top, message='', toggle_query=False, selected=None):
    cols, rows = terminal_size()
    status = f"{filt} [{len(view)} (1/1)]"
    prompt_text = f"{opts.prompt} {query}"
    if len(prompt_text) + len(status) + 1 < cols:
        line = prompt_text + ' '*(cols-len(prompt_text)-len(status)) + status
    else:
        line = prompt_text[:max(0,cols-len(status)-1)] + ' ' + status
    height_rows = rows
    if opts.height:
        try:
            if str(opts.height).endswith('%'):
                height_rows=max(3, int(rows*int(str(opts.height)[:-1])/100))
            else:
                height_rows=min(rows, int(opts.height)+2)
        except Exception:
            height_rows=rows
    list_rows = max(1, height_rows - (1 if opts.suppress_status else 2))
    if sel < top: top=sel
    if sel >= top+list_rows: top=sel-list_rows+1
    top=max(0,top)
    lines=[]
    if opts.layout == 'bottom-up':
        # keep a simple representation; selected item is still selected logically
        display_items = list(reversed(view[max(0, len(view)-list_rows):])) if len(view)>list_rows else list(reversed(view))
        lines.extend([format_item(it, opts, selected, False, cols) for it in display_items])
        lines.append(line[:cols])
    elif opts.layout == 'top-down-query-bottom':
        for i,it in enumerate(view[top:top+list_rows]):
            lines.append(format_item(it, opts, selected, top+i==sel, cols))
        lines.append(line[:cols])
    else:
        lines.append(line[:cols])
        for i,it in enumerate(view[top:top+list_rows]):
            lines.append(format_item(it, opts, selected, top+i==sel, cols))
    if not opts.suppress_status:
        lines.append((message or '')[:cols])
    # Clear and paint. tcell normally uses the alternate screen; this simple full repaint is enough for pty use.
    out='\x1b[?25l\x1b[H\x1b[2J' + '\r\n'.join(l.ljust(cols)[:cols] for l in lines[:height_rows])
    ttyf.write(out)
    ttyf.flush()
    return top


def format_item(it, opts, selected, cursor, cols):
    prefix=''
    if opts.selection_prefix is not None:
        prefix = opts.selection_prefix if (cursor or it.index in (selected or set())) else ' '*len(opts.selection_prefix)
    elif cursor:
        # capture-pane does not show attributes, but terminals do.
        prefix=''
    text=it.disp if hasattr(it,'disp') else it.display
    return (prefix + text)[:cols]


def action_from_key(opts, data):
    # Raw byte sequences to action names.
    if data in (b'\r', b'\n'): return 'finish'
    if data in (b'\x1b', b'\x03'): return 'cancel'
    if data in (b'\x7f', b'\b'): return 'backspace'
    if data == b'\x04': return 'del_forward'
    if data == b'\x01': return 'bol'
    if data == b'\x05': return 'eol'
    if data == b'\x0b': return 'kill_end'
    if data == b'\x15': return 'kill_begin'
    if data == b'\x17': return 'del_word'
    if data == b'\x0e': return 'down'
    if data == b'\x10': return 'up'
    if data == b'\x12': return 'rotate'
    if data == b'\x14': return 'toggle_query'
    if data == b'\x07': return 'select_none'
    if data == b'\x00': return 'toggle_select_next'
    if data in (b'\x1b[A',): return 'up'
    if data in (b'\x1b[B',): return 'down'
    if data in (b'\x1b[5~', b'\x1b[D'): return 'pageup'
    if data in (b'\x1b[6~', b'\x1b[C'): return 'pagedown'
    if data == b'\x1b[H' or data == b'\x1b[1~': return 'bol'
    if data == b'\x1b[F' or data == b'\x1b[4~': return 'eol'
    return None


def read_key(fd):
    b=os.read(fd,1)
    if not b: return b
    if b == b'\x1b':
        # collect the rest of a CSI sequence if available shortly
        seq=b
        for _ in range(8):
            r,_,_=select.select([fd],[],[],0.01)
            if not r: break
            c=os.read(fd,1); seq += c
            if (c >= b'@' and c <= b'~') and len(seq) >= 3: break
        return seq
    return b


def word_left_delete(q, cur):
    if cur <= 0: return q,cur
    i=cur
    while i>0 and q[i-1].isspace(): i-=1
    while i>0 and not q[i-1].isspace(): i-=1
    return q[:i]+q[cur:], i


def current_output_items(view, selected):
    if selected:
        order=sorted(selected)
        mapping={it.index:it for it in view}
        # If selected items are not currently visible, preserve original-order indices from the whole session via caller if possible.
        return [mapping[i] for i in order if i in mapping]
    return [view[0]] if view else []


def interactive(opts, items):
    # Open controlling terminal.  If this fails, match tcell's public error wording.
    if not os.environ.get('TERM',''):
        screen_error_and_exit()
    try:
        ttyf=open('/dev/tty','r+b', buffering=0)
    except Exception:
        screen_error_and_exit()
    fd=ttyf.fileno(); old=None
    query=opts.query; cur=len(query); filt=opts.initial_filter
    query_disabled=False; selected=set(); selection_order=[]
    view=filtered(items, query, filt, query_disabled)
    sel=clamp(opts.initial_index, 0, len(view)-1) if view else 0
    top=0
    try:
        old=termios.tcgetattr(fd); tty.setraw(fd)
        while True:
            view=filtered(items, query, filt, query_disabled)
            if view:
                sel=clamp(sel,0,len(view)-1)
            else:
                sel=0
            top=render(ttyf, opts, query, filt, view, sel, top, selected=selected)
            key=read_key(fd); act=action_from_key(opts, key)
            if act == 'finish':
                if opts.exec_cmd:
                    data=''.join(it.output+'\n' for it in (current_output_items(view,selected)))
                    try: subprocess.run(opts.exec_cmd, shell=True, input=data.encode(), stdout=sys.stdout, stderr=sys.stderr)
                    except Exception: pass
                    continue
                break
            if act == 'cancel':
                if old: termios.tcsetattr(fd, termios.TCSADRAIN, old); old=None
                ttyf.write(b'\x1b[?25h\x1b[H\x1b[2J'); ttyf.flush(); ttyf.close()
                sys.exit(0 if opts.on_cancel=='success' else 1)
            elif act == 'up': sel -= 1
            elif act == 'down': sel += 1
            elif act == 'pageup': sel -= max(1, terminal_size().lines-2)
            elif act == 'pagedown': sel += max(1, terminal_size().lines-2)
            elif act == 'backspace':
                if cur>0: query=query[:cur-1]+query[cur:]; cur-=1
            elif act == 'del_forward':
                if cur < len(query): query=query[:cur]+query[cur+1:]
                else:
                    if old: termios.tcsetattr(fd, termios.TCSADRAIN, old); old=None
                    ttyf.write(b'\x1b[?25h\x1b[H\x1b[2J'); ttyf.flush(); ttyf.close(); sys.exit(1)
            elif act == 'bol': cur=0
            elif act == 'eol': cur=len(query)
            elif act == 'kill_begin': query=query[cur:]; cur=0
            elif act == 'kill_end': query=query[:cur]
            elif act == 'del_word': query,cur=word_left_delete(query,cur)
            elif act == 'rotate':
                # peco's default rotation starts with ignore/no-ignore; full cycle is useful and close enough.
                idx=FILTERS.index(filt) if filt in FILTERS else 0; filt=FILTERS[(idx+1)%len(FILTERS)]
            elif act == 'toggle_query': query_disabled=not query_disabled
            elif act == 'select_none': selected.clear(); selection_order.clear()
            elif act == 'toggle_select_next':
                if view:
                    idx=view[sel].index
                    if idx in selected:
                        selected.remove(idx); selection_order=[x for x in selection_order if x!=idx]
                    else:
                        selected.add(idx); selection_order.append(idx)
                    sel += 1
            elif key and len(key)==1 and 32 <= key[0] < 127:
                ch=key.decode('utf-8','ignore'); query=query[:cur]+ch+query[cur:]; cur += len(ch)
            # clamp on next loop
        if old: termios.tcsetattr(fd, termios.TCSADRAIN, old); old=None
        ttyf.write(b'\x1b[?25h\x1b[H\x1b[2J'); ttyf.flush(); ttyf.close()
        # Recompute final view and output selected/current. Selected lines are returned in original input order.
        view=filtered(items, query, filt, query_disabled)
        if selected:
            byidx={it.index:it for it in items}
            out=[byidx[i] for i in sorted(selected) if i in byidx]
        else:
            out=[view[clamp(sel,0,len(view)-1)]] if view else []
        output_lines(opts, query, out)
        sys.exit(0)
    finally:
        try:
            if old: termios.tcsetattr(fd, termios.TCSADRAIN, old)
        except Exception: pass
        try: ttyf.write(b'\x1b[?25h')
        except Exception: pass


def main():
    argv=sys.argv[1:]
    try:
        opts,pos=parse_args(argv)
        apply_config(opts, None, argv)
    except ParseError as e:
        sys.stderr.write(e.msg + "\n")
        if e.show_help:
            sys.stderr.write(HELP)
            sys.stderr.write(f"Error: failed to setup peco: failed to parse command line: failed to parse command line options: invalid command line options: {e.msg}\n")
        else:
            sys.stderr.write(f"Error: failed to setup peco: failed to parse command line: failed to parse command line options: invalid command line arguments: {e.msg}\n")
        sys.exit(1)
    except SetupError as e:
        sys.stderr.write(f"Error: failed to setup peco: {e}\n"); sys.exit(1)
    try:
        items=read_items(opts,pos)
    except SetupError as e:
        sys.stderr.write(f"Error: {e}\n"); sys.exit(1)
    # Synchronous fast paths. peco intentionally does not take these when an initial query is set.
    if opts.query == '':
